import{_ as t,o,c as d,a1 as a}from"./chunks/framework.BKrM4vFX.js";const k=JSON.parse('{"title":"yookassa-mock — мок-стенд ЮKassa (REST /v3)","description":"yookassa-mock — мок-стенд ЮKassa (REST /v3). © 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0 Первый внешний банк-адаптер стенда (issue #33, Stage 2): мок воспроизводит мерчантский API ЮKassa по официальной докуме","frontmatter":{"sourcePath":"services/yookassa-mock/README.md"},"headers":[{"level":1,"title":"yookassa-mock — мок-стенд ЮKassa (REST /v3)","slug":"yookassa-mock-мок-стенд-Юkassa-rest-v3","link":"#yookassa-mock-мок-стенд-Юkassa-rest-v3","children":[{"level":2,"title":"Зачем","slug":"Зачем","link":"#Зачем","children":[]},{"level":2,"title":"Запуск","slug":"Запуск","link":"#Запуск","children":[]},{"level":2,"title":"API","slug":"api","link":"#api","children":[]},{"level":2,"title":"Машинка статусов","slug":"Машинка-статусов","link":"#Машинка-статусов","children":[]},{"level":2,"title":"Auth и идемпотентность","slug":"auth-и-идемпотентность","link":"#auth-и-идемпотентность","children":[]},{"level":2,"title":"Ошибки (формат ЮKassa + DX)","slug":"Ошибки-формат-Юkassa-dx","link":"#Ошибки-формат-Юkassa-dx","children":[]},{"level":2,"title":"Confirmation-страница и тестовые карты","slug":"confirmation-страница-и-тестовые-карты","link":"#confirmation-страница-и-тестовые-карты","children":[]},{"level":2,"title":"Вебхуки","slug":"Вебхуки","link":"#Вебхуки","children":[]},{"level":2,"title":"Сценарии (X-Mock-Scenario и /mock/scenarios)","slug":"Сценарии-x-mock-scenario-и-mockscenarios","link":"#Сценарии-x-mock-scenario-и-mockscenarios","children":[]},{"level":2,"title":"Виртуальные часы и TTL","slug":"Виртуальные-часы-и-ttl","link":"#Виртуальные-часы-и-ttl","children":[]},{"level":2,"title":"Переменные окружения","slug":"Переменные-окружения","link":"#Переменные-окружения","children":[]},{"level":2,"title":"Границы и документированные форки","slug":"Границы-и-документированные-форки","link":"#Границы-и-документированные-форки","children":[]},{"level":2,"title":"Байтовые квоты состояния (PD-02)","slug":"Байтовые-квоты-состояния-pd-02","link":"#Байтовые-квоты-состояния-pd-02","children":[]}]}],"relativePath":"services/yookassa-mock/README.md","filePath":"services/yookassa-mock/README.md"}'),c={name:"services/yookassa-mock/README.md"};function s(i,e,n,l,r,p){return o(),d("div",null,[...e[0]||(e[0]=[a(`<p>© 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0</p><h1 id="yookassa-mock-мок-стенд-Юkassa-rest-v3" tabindex="-1">yookassa-mock — мок-стенд ЮKassa (REST /v3) <a class="header-anchor" href="#yookassa-mock-мок-стенд-Юkassa-rest-v3" aria-label="Permalink to &quot;yookassa-mock — мок-стенд ЮKassa (REST /v3)&quot;">​</a></h1><p>Первый внешний банк-адаптер стенда (issue #33, Stage 2): мок воспроизводит мерчантский API ЮKassa по официальной документации (<a href="https://yookassa.ru/developers" target="_blank" rel="noreferrer">https://yookassa.ru/developers</a>) — Basic Auth, <code>Idempotence-Key</code>, платежи <code>pending → waiting_for_capture → succeeded | canceled</code>, возвраты, confirmation-страница с тестовыми картами и вебхуки <code>{type, event, object}</code> без подписи (ACK — ровно HTTP 200). Исходная исследовательская база — <code>документации ЮKassa*</code>; публичный гайд — <code>docs/integration/yookassa.md</code>.</p><p>Node.js &gt;= 18; внешние npm-зависимости не нужны. Все слои переиспользованы из <code>packages/core</code> по паттерну tbank-mock: журнал с редакцией секретов и curl, очередь доставки вебхуков (ретраи, SSRF-guard), сценарный реестр, виртуальные часы, control-plane токены, sandbox runtime RFC-001.</p><h2 id="Зачем" tabindex="-1">Зачем <a class="header-anchor" href="#Зачем" aria-label="Permalink to &quot;Зачем&quot;">​</a></h2><p>Реальный тестовый контур ЮKassa требует договора и секретных ключей в кабинете. Мок даёт управляемые локальные сценарии: two-stage-холд с частичным capture, отказы карт с честными <code>cancellation_details</code>, ретраи/дубли вебхуков, истечение холда по виртуальным часам — всё без обращения к боевому API.</p><h2 id="Запуск" tabindex="-1">Запуск <a class="header-anchor" href="#Запуск" aria-label="Permalink to &quot;Запуск&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yookassa-mock</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # порт 3102</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># или голым node</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:yookassa</span></span></code></pre></div><p>Стартовый лог печатает дефолтные тестовые креды:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[yookassa-mock] basic auth: shopId=YOOKASSAMOCKTEST secret=mockpass123 (тестовые креды, MOCK_SHOP_ID/MOCK_SECRET_KEY переопределяют)</span></span></code></pre></div><p>Самотест (246 проверок: контракт /v3, идемпотентность, карты, вебхуки, сценарии, часы, песочницы, рестарт, control-plane):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:yookassa</span></span></code></pre></div><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Маршрут</th><th>Поведение</th></tr></thead><tbody><tr><td><code>POST /v3/payments</code></td><td>создаёт платёж: <code>amount</code> (decimal-строка, только <code>RUB</code>), <code>capture</code> (не передан → <code>true</code>), <code>confirmation.type=redirect</code> + <code>return_url</code>, <code>description</code> ≤128, <code>metadata</code> ≤16 ключей. Ответ — объект платежа <code>pending</code> + <code>confirmation.confirmation_url</code></td></tr><tr><td><code>GET /v3/payments</code></td><td><code>{type:&quot;list&quot;, items, next_cursor}</code> (без фильтров/пагинации — см. «Границы»)</td></tr><tr><td><code>GET /v3/payments/{id}</code></td><td>объект платежа; неизвестный id → <code>404 not_found</code> c <code>parameter: payment_id</code></td></tr><tr><td><code>POST /v3/payments/{id}/capture</code></td><td>принимает hold: без <code>amount</code> — полный, с <code>amount</code> ≤ авторизованного — частичный (лимит возвратов = удержанная сумма). Только из <code>waiting_for_capture</code></td></tr><tr><td><code>POST /v3/payments/{id}/cancel</code></td><td>отмена мерчантом: <code>cancellation_details {party:&quot;merchant&quot;, reason:&quot;canceled_by_merchant&quot;}</code>. Только из <code>pending</code>/<code>waiting_for_capture</code></td></tr><tr><td><code>POST /v3/refunds</code></td><td>возврат по <code>succeeded</code>-платежу: <code>payment_id</code> + <code>amount</code>; <code>MOCK_REFUND_DELAY_MS=0</code> (дефолт) — сразу <code>succeeded</code>, как в официальных примерах; иначе <code>pending</code> → <code>succeeded</code> по тику</td></tr><tr><td><code>GET /v3/refunds</code></td><td><code>{type:&quot;list&quot;, items, next_cursor}</code></td></tr><tr><td><code>GET /v3/refunds/{id}</code></td><td>объект возврата; неизвестный id → <code>404 not_found</code> c <code>parameter: refund_id</code></td></tr><tr><td><code>GET /payment/{id}</code></td><td>confirmation-страница (тестовые карты, пресеты)</td></tr><tr><td><code>POST /payment/{id}/pay</code>, <code>/3ds</code></td><td>оплата картой, 3DS-challenge; успех и отказ ведут <code>302</code> на <code>return_url</code></td></tr><tr><td><code>GET /health</code>, <code>GET /admin</code>, <code>GET /admin/journal</code></td><td>healthcheck и админ-консоль с curl-сниппетами</td></tr><tr><td><code>/mock/time</code>, <code>/mock/scenarios</code>, <code>/mock/state</code>, <code>/mock/reset</code>, <code>/sandboxes*</code></td><td>общий control-plane (см. <code>packages/core/README.md</code>)</td></tr></tbody></table><p>Успешный ответ всех операций — <strong>HTTP 200</strong> с объектом (как у ЮKassa).</p><h2 id="Машинка-статусов" tabindex="-1">Машинка статусов <a class="header-anchor" href="#Машинка-статусов" aria-label="Permalink to &quot;Машинка статусов&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pending ──оплата capture=true──► succeeded ──► возвраты (refunded_amount растёт)</span></span>
<span class="line"><span>   │                               ▲</span></span>
<span class="line"><span>   │ оплата capture=false          │ capture (полный/частичный)</span></span>
<span class="line"><span>   ▼                               │</span></span>
<span class="line"><span>waiting_for_capture ───────────────┘</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├── cancel (merchant) ───────────────► canceled</span></span>
<span class="line"><span>   ├── истечение холда (7 дней) ────────► canceled {yoo_money, expired_on_capture}</span></span>
<span class="line"><span>pending</span></span>
<span class="line"><span>   ├── отказ карты на форме ────────────► canceled {party/ reason из таблицы}</span></span>
<span class="line"><span>   ├── cancel (merchant) ───────────────► canceled {merchant, canceled_by_merchant}</span></span>
<span class="line"><span>   └── MOCK_PENDING_TTL_MS &gt; 0, истёк ──► canceled {yoo_money, expired_on_confirmation}</span></span></code></pre></div><p><code>party</code> для отказов карт — по официальной таблице declined-payments: <code>payment_network</code> (эмитент/схема: insufficient_funds, call_issuer, …), <code>yoo_money</code> (fraud_suspected — блокировка ЮKassa), <code>merchant</code> (API-отмена).</p><h2 id="auth-и-идемпотентность" tabindex="-1">Auth и идемпотентность <a class="header-anchor" href="#auth-и-идемпотентность" aria-label="Permalink to &quot;Auth и идемпотентность&quot;">​</a></h2><ul><li><strong>Basic Auth</strong> на все <code>/v3/*</code>: <code>Authorization: Basic base64(shopId:secretKey)</code>. Дефолт <code>YOOKASSAMOCKTEST:mockpass123</code>; переопределяется <code>MOCK_SHOP_ID</code> / <code>MOCK_SECRET_KEY</code> (или <code>YOOKASSA_*</code>). Неверные креды → <code>401 invalid_credentials</code>.</li><li><strong><code>Idempotence-Key</code> обязателен для POST /v3</strong> (≤64 символов): <ul><li>ключа нет → <code>400 invalid_request</code>, <code>parameter: Idempotence-Key</code>, официальный текст <code>Idempotence key is missing. …</code>;</li><li>повтор того же ключа с тем же endpoint и телом → сохранённый ответ «как есть» (заголовок <code>X-Idempotence-Replayed: 1</code>), повтор не создаёт второй платёж;</li><li>тот же ключ с другим телом → <code>400 invalid_request</code> «Idempotence key duplicated»;</li><li>хэш считается по raw-телу; ключи живут в state (переживают рестарт), FIFO на <code>1000</code> записей;</li><li>GET ключ не требует.</li></ul></li></ul><h2 id="Ошибки-формат-Юkassa-dx" tabindex="-1">Ошибки (формат ЮKassa + DX) <a class="header-anchor" href="#Ошибки-формат-Юkassa-dx" aria-label="Permalink to &quot;Ошибки (формат ЮKassa + DX)&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2b6…uuid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;invalid_request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Invalid parameter&#39;s value: amount.value must be …&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;parameter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;amount.value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…человекочитаемое объяснение на русском…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;doc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://yookassa.ru/developers/…&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>HTTP-маппинг (как в официальном response-handling): <code>400 invalid_request</code>, <code>401 invalid_credentials</code>, <code>403 forbidden</code>, <code>404 not_found</code>, <code>429 too_many_requests</code>, <code>500 internal_server_error</code>. Поля <code>hint</code> и <code>doc</code> — DX-слой мока (не часть протокола ЮKassa): каждое отклонение объясняет, что поправить и где это описано в документации.</p><p><strong>Форк (решение координатора):</strong> <code>405</code>/<code>415</code> отдаются с <strong>пустым телом</strong> — как в официальной документации ЮKassa; DX-слой эти два кода не покрывает.</p><h2 id="confirmation-страница-и-тестовые-карты" tabindex="-1">Confirmation-страница и тестовые карты <a class="header-anchor" href="#confirmation-страница-и-тестовые-карты" aria-label="Permalink to &quot;Confirmation-страница и тестовые карты&quot;">​</a></h2><p><code>confirmation.confirmation_url</code> ведёт на <code>/payment/{id}</code> — страница с пресетами тестовых карт (<code>документации ЮKassa</code>):</p><ul><li>успех: <code>5555555555554444</code>, <code>4111111111111111</code>, <code>4175001000000017</code> (без 3DS), <code>5555555555554477</code>, <code>4793128161644804</code> (3DS-challenge, код — любые ≥4 цифр);</li><li>отказы по причинам: <code>5555555555554600</code> → <code>insufficient_funds</code>, <code>5555555555554618</code> → <code>invalid_card_number</code>, <code>5555555555554592</code> → <code>3d_secure_failed</code>, <code>5555555555554568</code> → <code>fraud_suspected</code> и т.д. (в README гайда — полная таблица);</li><li>неизвестная Luhn-валидная карта → <code>general_decline</code>; невалидный Luhn → <code>invalid_card_number</code>; просроченный срок → <code>card_expired</code>;</li><li>форматные ошибки формы (не цифры, кривой CVC) показываются на странице и <strong>не</strong> меняют платёж.</li></ul><p>В state попадают только <code>first6</code>/<code>last4</code>/срок — полный PAN не хранится и не попадает в журнал (F-10).</p><h2 id="Вебхуки" tabindex="-1">Вебхуки <a class="header-anchor" href="#Вебхуки" aria-label="Permalink to &quot;Вебхуки&quot;">​</a></h2><p><code>{ &quot;type&quot;: &quot;notification&quot;, &quot;event&quot;: &quot;…&quot;, &quot;object&quot;: {…} }</code> на <code>MOCK_DEFAULT_WEBHOOK_URL</code> (или mock-расширение <code>metadata.webhook_url</code> у платежа — переопределяет адрес). События: <code>payment.succeeded</code>, <code>payment.waiting_for_capture</code>, <code>payment.canceled</code>, <code>refund.succeeded</code> — на каждый переход статуса. Подписи нет (протокол ЮKassa её не предусматривает — проверять нечего, «изобретать» не нужно). ACK — <strong>ровно HTTP 200</strong>, тело игнорируется: до 200 доставка повторяется (<code>MOCK_RETRY_MS</code> × <code>MOCK_MAX_ATTEMPTS</code>); очередь, ретраи, SSRF-guard — ядро (<code>createDeliveryQueue</code>). Сценарии <code>webhook-drop|no-webhook</code> подавляют событие, <code>webhook-duplicate</code> кладёт две копии (приёмник должен быть идемпотентен — кнопка «повторить» есть в <code>/admin</code>).</p><h2 id="Сценарии-x-mock-scenario-и-mockscenarios" tabindex="-1">Сценарии (X-Mock-Scenario и /mock/scenarios) <a class="header-anchor" href="#Сценарии-x-mock-scenario-и-mockscenarios" aria-label="Permalink to &quot;Сценарии (X-Mock-Scenario и /mock/scenarios)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Сценарий</th><th>Эффект</th></tr></thead><tbody><tr><td><code>fail</code></td><td>POST /v3 → <code>500 internal_server_error</code> в формате ЮKassa, бизнес не выполняется</td></tr><tr><td><code>hang</code></td><td>запрос не получает ответа (проверяйте таймауты клиента)</td></tr><tr><td><code>latency:2s</code>, <code>X-Mock-Latency</code></td><td>задержка ответа (ядро)</td></tr><tr><td><code>http-500</code>, <code>http-504</code></td><td>сетевой сбой до бизнес-логики (ядро, <code>abortStatus</code>)</td></tr><tr><td><code>webhook-drop</code>, <code>no-webhook</code></td><td>подавить вебхуки перехода</td></tr><tr><td><code>webhook-duplicate</code></td><td>две копии события</td></tr></tbody></table><p>Правила без заголовка — <code>POST /mock/scenarios {scenario, target, match, times}</code>. История триггеров — <code>GET /mock/scenarios</code>.</p><p>Правила, история срабатываний и журнал <code>/admin/journal</code> принадлежат текущей песочнице (#52): другие песочницы их не видят и не очищают, <code>POST /mock/reset</code> действует только на целевую песочницу. Лимиты: до 200 правил на песочницу и до 8 KiB на правило (превышение — HTTP 400 с <code>code</code> <code>rule_cap_exceeded</code>/<code>rule_too_large</code>).</p><h2 id="Виртуальные-часы-и-ttl" tabindex="-1">Виртуальные часы и TTL <a class="header-anchor" href="#Виртуальные-часы-и-ttl" aria-label="Permalink to &quot;Виртуальные часы и TTL&quot;">​</a></h2><ul><li>холд <code>waiting_for_capture</code>: 7 дней (<code>MOCK_CAPTURE_TTL_MS</code>, как в докам для карт) → авто-отмена <code>expired_on_capture</code>; ускоряется <code>POST /mock/time {&quot;advance&quot;:&quot;+7d&quot;}</code> — проверка в selftest;</li><li><code>pending</code>: <code>MOCK_PENDING_TTL_MS</code> (0 — выключено) → <code>expired_on_confirmation</code>;</li><li><code>MOCK_REFUND_DELAY_MS</code> — задержка финализации возврата (0 — сразу <code>succeeded</code>, дефолт как в официальных примерах).</li></ul><h2 id="Переменные-окружения" tabindex="-1">Переменные окружения <a class="header-anchor" href="#Переменные-окружения" aria-label="Permalink to &quot;Переменные окружения&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Переменная</th><th>Дефолт</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_HOST</code> / <code>MOCK_PORT</code></td><td><code>0.0.0.0</code> / <code>3102</code></td><td>адрес и порт прослушивания</td></tr><tr><td><code>MOCK_SHOP_ID</code> / <code>MOCK_SECRET_KEY</code></td><td><code>YOOKASSAMOCKTEST</code> / <code>mockpass123</code></td><td>Basic-креды (алиасы <code>YOOKASSA_SHOP_ID</code>, <code>YOOKASSA_SECRET_KEY</code>)</td></tr><tr><td><code>MOCK_PUBLIC_BASE_URL</code></td><td><code>http://localhost:\${MOCK_YOOKASSA_HOST_PORT:-3102}</code></td><td>база <code>confirmation_url</code></td></tr><tr><td><code>MOCK_DEFAULT_WEBHOOK_URL</code></td><td>—</td><td>приёмник вебхуков магазина</td></tr><tr><td><code>MOCK_RETRY_MS</code> / <code>MOCK_MAX_ATTEMPTS</code></td><td><code>60000</code> / <code>24</code></td><td>ретраи вебхуков (в selftest — 1000)</td></tr><tr><td><code>MOCK_CAPTURE_TTL_MS</code></td><td>7 дней</td><td>удержание <code>waiting_for_capture</code></td></tr><tr><td><code>MOCK_PENDING_TTL_MS</code></td><td><code>0</code></td><td>авто-отмена <code>pending</code> (0 — выкл.)</td></tr><tr><td><code>MOCK_REFUND_DELAY_MS</code></td><td><code>0</code></td><td>задержка финализации возврата</td></tr><tr><td><code>MOCK_STATE_FILE</code></td><td>—</td><td>файл состояния (compose: <code>/data/yookassa-state.json</code>)</td></tr><tr><td><code>MOCK_BLOCK_PRIVATE_WEBHOOKS</code></td><td>с <code>MOCK_HOSTED</code></td><td>SSRF-guard исходящих вебхуков</td></tr><tr><td><code>MOCK_ADMIN_TOKEN</code>, <code>MOCK_OPERATOR_TOKEN</code>, <code>MOCK_HOSTED</code>, <code>MOCK_TENANCY</code>, <code>MOCK_SANDBOX_*</code></td><td>—</td><td>общий control-plane (см. README ядра)</td></tr><tr><td><code>MOCK_VIRTUAL_CLOCK</code></td><td>—</td><td>ISO-старт виртуальных часов стенда (TTL холда 7 дней, авто-отмена <code>pending</code>, ретраи вебхуков)</td></tr></tbody></table><h2 id="Границы-и-документированные-форки" tabindex="-1">Границы и документированные форки <a class="header-anchor" href="#Границы-и-документированные-форки" aria-label="Permalink to &quot;Границы и документированные форки&quot;">​</a></h2><p>Что мок <strong>не</strong> делает (осознанно, вне scope #33):</p><ul><li><code>receipt</code> принимается и хранится как есть, но <strong>не валидируется</strong> и не фискализируется (54-ФЗ — в <code>kassa-mock</code>);</li><li><code>save_payment_method</code>, рекурренты, <code>transfers</code>/<code>deal</code>, <code>payment_token</code> (Checkout.js) не моделируются;</li><li>списки <code>GET /v3/payments|refunds</code> — без фильтров и курсорной пагинации (<code>next_cursor: null</code>);</li><li>confirmation кроме <code>redirect</code> (<code>embedded</code> и др.) → <code>400</code> с hint;</li><li><code>/openapi.json</code> и манифест <code>protocols/yookassa.json</code> не ведутся (не в DoD #33; дрейф-чекер их не покрывает);</li><li><code>/mock/verify-merchant</code> не реализован: вебхуки ЮKassa не подписаны, ветка ядра <code>verifyMerchantWebhook</code> умеет tbank/ferma, а правка ядра требует санкции координатора (вопрос вынесен в отчёт PR);</li><li><code>405</code>/<code>415</code> — пустое тело (официальная семантика; см. выше), <code>capture</code> при создании не передан → <code>true</code> (простой сценарий quick-start; серверный дефолт ЮKassa официально не документирован);</li><li><code>metadata.webhook_url</code> — mock-расширение для подмены адреса приёмника конкретного платежа (в бою metadata — «чёрный ящик», протокол не нарушает).</li></ul><p>Контракты <code>tbank-mock</code> и <code>kassa-mock</code> не менялись (selftest: 38/48+129/0).</p><h2 id="Байтовые-квоты-состояния-pd-02" tabindex="-1">Байтовые квоты состояния (PD-02) <a class="header-anchor" href="#Байтовые-квоты-состояния-pd-02" aria-label="Permalink to &quot;Байтовые квоты состояния (PD-02)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Env</th><th>Дефолт</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_SANDBOX_MAX_STATE_BYTES</code></td><td>пусто: <code>8388608</code> (8 МиБ) при <code>maxDocuments &gt; 0</code>, иначе без лимита</td><td>байты JSON одной песочницы; <code>0</code> выключает</td></tr><tr><td><code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code></td><td><code>67108864</code> (64 МиБ)</td><td>сумма байт JSON всех песочниц рантайма, включая <code>default</code>; <code>0</code> выключает</td></tr></tbody></table><p>Значения задаются в целых байтах. Пусто сохраняет дефолты. Квота per-sandbox не ограничивает память контейнера; общий бюджет меньше <code>mem_limit: 128m</code>, но не равен RSS. Превышение глобального бюджета на записи или байтовых квот при импорте <code>/mock/state</code> → HTTP 400, <code>errorCode: 400</code>, <code>kind: &#39;bytes&#39;</code>, <code>code: sandbox_state_budget_exceeded</code> / <code>sandbox_state_quota_exceeded</code>, с откатом отклонённого состояния. Правила/история/журнал остаются volatile. Подробности и границы — <a href="./../../packages/core/README#байтовые-квоты-песочниц-pd-02-74">документация ядра</a>.</p>`,46)])])}const _=t(c,[["render",s]]);export{k as __pageData,_ as default};
